from typing import Iterable, List, Mapping, Dict
from stockflow.parse_movement_line import parse_movement_line

def dead_stock(lines: Iterable[str], case_sizes: Mapping[str, int], today: int, idle_days: int) -> List[str]:
    if idle_days < 1:
        raise ValueError("idle_days must be at least 1")

    sku_on_hand: Dict[str, int] = {}
    sku_last_ship: Dict[str, int] = {}

    for line in lines:
        text = line.strip()
        if not text or text.startswith("#"):
            continue

        m = parse_movement_line(text, case_sizes)
        if m["day"] > today:
            continue

        sku = m["sku"]
        sku_on_hand[sku] = sku_on_hand.get(sku, 0) + m["qty"]
        if m["type"] == "SHP":
            if m["day"] > sku_last_ship.get(sku, -1):
                sku_last_ship[sku] = m["day"]

    dead_skus = []
    for sku, on_hand in sku_on_hand.items():
        if on_hand > 0:
            last_ship = sku_last_ship.get(sku, -float('inf'))
            if today - last_ship >= idle_days:
                dead_skus.append(sku)

    return sorted(dead_skus)"
