This is the "ship complete" edge case — an order only gets stock if it can be fully filled; otherwise it gets nothing (defers to later orders). My greedy partial-fill was wrong. Let me rewrite.

{"thought": "Implement all-or-nothing per order: an order is filled only if every line can be fully satisfied; partial orders get 0 and stock stays available for later orders.", "action": {"tool": "write_file", "args": {"path": "src/stockflow/allocate_backorders.py", "content": "from __future__ import annotations

from typing import Dict, Mapping, Sequence, Tuple


def allocate_backorders(orders: Sequence[Tuple[str, int, int, Mapping[str, int]]], available: Mapping[str, int]) -> Dict[str, Dict[str, int]]:
    """
    Allocate available stock to open customer backorders.

    Args:
        orders: (order_id, priority, order_day, lines) tuples, where lines maps
            SKU -> backordered eaches. Priority 1 is the most urgent; larger
            numbers are less urgent.
        available: SKU -> eaches available to promise. SKUs that are missing
            have 0 available.

    Orders are served one after another in this sequence: priority ascending,
    then order_day ascending, then order_id ascending. An order is only filled
    if every line can be fully satisfied from the remaining stock (ship-complete);
    an order that cannot be fully filled is allocated nothing, and its lines
    remain available to later orders.

    Returns:
        Dict order_id -> {sku: allocated eaches} with an entry for every order and
        every SKU on its lines (0 where nothing was allocated). The inputs are not
        modified.

    Raises:
        ValueError: on a duplicate order_id or a line qty <= 0.

    Example:
        allocate_backorders([("o1", 2, 10, {"S": 5}), ("o2", 1, 12, {"S": 4})], {"S": 4})
            == {"o1": {"S": 0}, "o2": {"S": 4}}
    """
    seen = set()
    for order_id, _priority, _order_day, lines in orders:
        if order_id in seen:
            raise ValueError(f"duplicate order_id: {order_id}")
        seen.add(order_id)
        for sku, qty in lines.items():
            if qty <= 0:
                raise ValueError(f"line qty <= 0 for order {order_id} sku {sku}: {qty}")

    remaining = {sku: int(qty) for sku, qty in available.items()}

    def sort_key(order):
        order_id, priority, order_day, _lines = order
        return (priority, order_day, order_id)

    result: Dict[str, Dict[str, int]] = {}
    for order_id, _priority, _order_day, lines in sorted(orders, key=sort_key):
        # Ship-complete: only allocate if every line can be fully satisfied.
        if all(remaining.get(sku, 0) >= qty for sku, qty in lines.items()):
            for sku, qty in lines.items():
                remaining[sku] -= qty
            result[order_id] = {sku: qty for sku, qty in lines.items()}
        else:
            result[order_id] = {sku: 0 for sku in lines}

    return result
"}}, "messages": []}

