from stockflow.first_fit_decreasing import first_fit_decreasing


def split_shipment(lines: Sequence[Tuple[str, int, int]], max_parcel_grams: int) -> List[Dict[str, int]]:
    """Split an order into parcels that each fit under the carrier weight limit.

    ``lines`` is a sequence of ``(sku, qty, unit_weight_grams)`` tuples.
    ``max_parcel_grams`` is the per-parcel weight limit.

    Returns a list of parcels, each a ``{sku: qty}`` dict, such that every
    parcel's total weight is at most ``max_parcel_grams``. Units of the same
    SKU are interchangeable and may be split across parcels; packing is done
    with first-fit-decreasing over individual units.

    Raises ``ValueError`` if ``max_parcel_grams`` is not positive, if any
    quantity or unit weight is not positive, if any single unit exceeds the
    limit, or if the same SKU is given conflicting unit weights.
    """
    if max_parcel_grams <= 0:
        raise ValueError("max_parcel_grams must be positive")

    unit_weight: Dict[str, int] = {}
    total_qty: Dict[str, int] = {}
    for sku, qty, weight in lines:
        if qty <= 0 or weight <= 0:
            raise ValueError("qty and unit weight must be positive")
        if weight > max_parcel_grams:
            raise ValueError(f"{sku} is heavier than the parcel limit")
        if sku in unit_weight and unit_weight[sku] != weight:
            raise ValueError(f"conflicting unit weights for {sku}")
        unit_weight[sku] = weight
        total_qty[sku] = total_qty.get(sku, 0) + qty

    items = []
    for sku, weight in unit_weight.items():
        items.extend([(sku, weight)] * total_qty[sku])

    parcels: List[Dict[str, int]] = []
    for packed in first_fit_decreasing(items, max_parcel_grams):
        parcel: Dict[str, int] = {}
        for sku, _weight in packed:
            parcel[sku] = parcel.get(sku, 0) + 1
        parcels.append(parcel)
    return parcels
"}}, "messages": []}

